  CONSTRAINT fk_employees_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT uq_employees_employee_code UNIQUE (company_id, employee_code),
  INDEX ix_employees_company (company_id),
  INDEX ix_employees_user_id (user_id),
  INDEX ix_employees_driver_id (driver_id),
  INDEX ix_employees_department_id (department_id),
  INDEX ix_employees_branch_id (branch_id),
  INDEX ix_employees_shift_id (shift_id)
) ENGINE=InnoDB;

CREATE TABLE attendance (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  employee_id BIGINT NOT NULL,
  work_date DATE NOT NULL,
  check_in DATETIME(3),
  check_out DATETIME(3),
  status VARCHAR(20) NOT NULL DEFAULT 'PRESENT',
  lat DECIMAL(10,7),
  lng DECIMAL(10,7),
  notes VARCHAR(300),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_attendance_employee_id FOREIGN KEY (employee_id) REFERENCES employees(id),
  CONSTRAINT fk_attendance_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT uq_attendance_employee_id_work_date UNIQUE (company_id, employee_id, work_date),
  INDEX ix_attendance_company (company_id),
  INDEX ix_attendance_employee_id (employee_id)
) ENGINE=InnoDB;

CREATE TABLE leave_requests (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  employee_id BIGINT NOT NULL,
  leave_type VARCHAR(30) NOT NULL,
  from_date DATE NOT NULL,
  to_date DATE NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  reason VARCHAR(300),
  decided_by BIGINT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_leave_requests_employee_id FOREIGN KEY (employee_id) REFERENCES employees(id),
  CONSTRAINT fk_leave_requests_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_leave_requests_company (company_id),
  INDEX ix_leave_requests_employee_id (employee_id)
) ENGINE=InnoDB;

CREATE TABLE tasks (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  title VARCHAR(160) NOT NULL,
  description TEXT,
  assigned_employee_id BIGINT,
  due_date DATE,
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN',
  priority VARCHAR(10),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_tasks_assigned_employee_id FOREIGN KEY (assigned_employee_id) REFERENCES employees(id),
  CONSTRAINT fk_tasks_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_tasks_company (company_id),
  INDEX ix_tasks_assigned_employee_id (assigned_employee_id)
) ENGINE=InnoDB;

CREATE TABLE salary_structures (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  employee_id BIGINT NOT NULL,
  model VARCHAR(20) NOT NULL DEFAULT 'FIXED',
  monthly_salary DECIMAL(12,2),
  overtime_rate DECIMAL(12,2),
  per_delivery_rate DECIMAL(12,2),
  per_trip_rate DECIMAL(12,2),
  per_km_rate DECIMAL(12,4),
  per_task_rate DECIMAL(12,2),
  effective_from DATE,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_salary_structures_employee_id FOREIGN KEY (employee_id) REFERENCES employees(id),
  CONSTRAINT fk_salary_structures_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT uq_salary_structures_employee_id UNIQUE (company_id, employee_id),
  INDEX ix_salary_structures_company (company_id),
  INDEX ix_salary_structures_employee_id (employee_id)
) ENGINE=InnoDB;

CREATE TABLE work_records (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  employee_id BIGINT NOT NULL,
  work_type VARCHAR(20) NOT NULL,
  reference_id BIGINT,
  quantity DECIMAL(10,2) NOT NULL,
  rate DECIMAL(12,2),
  amount DECIMAL(12,2),
  work_date DATE NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  approved_by BIGINT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_work_records_employee_id FOREIGN KEY (employee_id) REFERENCES employees(id),
  CONSTRAINT fk_work_records_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_work_records_company (company_id),
  INDEX ix_work_records_employee_id (employee_id)
) ENGINE=InnoDB;

CREATE TABLE salary_advances (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  employee_id BIGINT NOT NULL,
  amount DECIMAL(12,2) NOT NULL,
  advance_date DATE NOT NULL,
  repaid DECIMAL(12,2) DEFAULT 0,
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_salary_advances_employee_id FOREIGN KEY (employee_id) REFERENCES employees(id),
  CONSTRAINT fk_salary_advances_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_salary_advances_company (company_id),
  INDEX ix_salary_advances_employee_id (employee_id)
) ENGINE=InnoDB;

CREATE TABLE payroll_runs (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  period_month VARCHAR(7) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
  total_net DECIMAL(14,2),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_payroll_runs_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT uq_payroll_runs_period_month UNIQUE (company_id, period_month),
  INDEX ix_payroll_runs_company (company_id)
) ENGINE=InnoDB;

CREATE TABLE payslips (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  payroll_run_id BIGINT,
  employee_id BIGINT NOT NULL,
  period_month VARCHAR(7) NOT NULL,
  model VARCHAR(20),
  basic DECIMAL(12,2),
  overtime DECIMAL(12,2),
  bonus DECIMAL(12,2),
  deductions DECIMAL(12,2),
  advances DECIMAL(12,2),
  work_earnings DECIMAL(12,2),
  net_salary DECIMAL(12,2) NOT NULL,
  working_days INT,
  present_days INT,
  leave_days INT,
  status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
  paid_on DATE,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_payslips_payroll_run_id FOREIGN KEY (payroll_run_id) REFERENCES payroll_runs(id),
  CONSTRAINT fk_payslips_employee_id FOREIGN KEY (employee_id) REFERENCES employees(id),
  CONSTRAINT fk_payslips_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT uq_payslips_employee_id_period_month UNIQUE (company_id, employee_id, period_month),
  INDEX ix_payslips_company (company_id),
  INDEX ix_payslips_payroll_run_id (payroll_run_id),
  INDEX ix_payslips_employee_id (employee_id)
) ENGINE=InnoDB;

CREATE TABLE inventory_items (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  warehouse_id BIGINT NOT NULL,
  sku VARCHAR(60) NOT NULL,
  name VARCHAR(160) NOT NULL,
  barcode VARCHAR(80),
  quantity INT DEFAULT 0,
  unit VARCHAR(20),
  reorder_level INT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_inventory_items_warehouse_id FOREIGN KEY (warehouse_id) REFERENCES warehouses(id),
  CONSTRAINT fk_inventory_items_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT uq_inventory_items_warehouse_id_sku UNIQUE (company_id, warehouse_id, sku),
  INDEX ix_inventory_items_company (company_id),
  INDEX ix_inventory_items_warehouse_id (warehouse_id)
) ENGINE=InnoDB;

CREATE TABLE stock_transfers (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  from_warehouse_id BIGINT NOT NULL,
  to_warehouse_id BIGINT NOT NULL,
  item_id BIGINT NOT NULL,
  quantity INT NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'COMPLETED',
  transferred_at DATETIME(3),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_stock_transfers_from_warehouse_id FOREIGN KEY (from_warehouse_id) REFERENCES warehouses(id),
  CONSTRAINT fk_stock_transfers_to_warehouse_id FOREIGN KEY (to_warehouse_id) REFERENCES warehouses(id),
  CONSTRAINT fk_stock_transfers_item_id FOREIGN KEY (item_id) REFERENCES inventory_items(id),
  CONSTRAINT fk_stock_transfers_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_stock_transfers_company (company_id),
  INDEX ix_stock_transfers_from_warehouse_id (from_warehouse_id),
  INDEX ix_stock_transfers_to_warehouse_id (to_warehouse_id),
  INDEX ix_stock_transfers_item_id (item_id)
) ENGINE=InnoDB;

CREATE TABLE inventory_history (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  item_id BIGINT NOT NULL,
  change_qty INT NOT NULL,
  reason VARCHAR(60),
  ref_type VARCHAR(40),
  ref_id BIGINT,
  balance_after INT,
  occurred_at DATETIME(3) NOT NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_inventory_history_item_id FOREIGN KEY (item_id) REFERENCES inventory_items(id),
  CONSTRAINT fk_inventory_history_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_inventory_history_company (company_id),
  INDEX ix_inventory_history_item_id (item_id)
) ENGINE=InnoDB;

CREATE TABLE invoices (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  invoice_number VARCHAR(30) NOT NULL,
  kind VARCHAR(10) NOT NULL,
  customer_id BIGINT,
  vendor_id BIGINT,
  shipment_id BIGINT,
  issue_date DATE NOT NULL,
  due_date DATE,
  subtotal DECIMAL(14,2),
  tax DECIMAL(14,2),
  total DECIMAL(14,2) NOT NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',
  currency VARCHAR(3),
  notes TEXT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_invoices_customer_id FOREIGN KEY (customer_id) REFERENCES customers(id),
  CONSTRAINT fk_invoices_vendor_id FOREIGN KEY (vendor_id) REFERENCES vendors(id),
  CONSTRAINT fk_invoices_shipment_id FOREIGN KEY (shipment_id) REFERENCES shipments(id),
  CONSTRAINT fk_invoices_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT uq_invoices_invoice_number UNIQUE (company_id, invoice_number),
  INDEX ix_invoices_company (company_id),
  INDEX ix_invoices_customer_id (customer_id),
  INDEX ix_invoices_vendor_id (vendor_id),
  INDEX ix_invoices_shipment_id (shipment_id)
) ENGINE=InnoDB;

CREATE TABLE payments (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  invoice_id BIGINT,
  direction VARCHAR(10) NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  method VARCHAR(30),
  reference VARCHAR(120),
  paid_at DATETIME(3) NOT NULL,
  gateway_ref VARCHAR(120),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_payments_invoice_id FOREIGN KEY (invoice_id) REFERENCES invoices(id),
  CONSTRAINT fk_payments_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_payments_company (company_id),
  INDEX ix_payments_invoice_id (invoice_id)
) ENGINE=InnoDB;

CREATE TABLE expenses (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  category VARCHAR(40) NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  expense_date DATE NOT NULL,
  vehicle_id BIGINT,
  vendor_id BIGINT,
  description VARCHAR(300),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_expenses_vehicle_id FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
  CONSTRAINT fk_expenses_vendor_id FOREIGN KEY (vendor_id) REFERENCES vendors(id),
  CONSTRAINT fk_expenses_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_expenses_company (company_id),
  INDEX ix_expenses_vehicle_id (vehicle_id),
  INDEX ix_expenses_vendor_id (vendor_id)
) ENGINE=InnoDB;

CREATE TABLE notifications (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  user_id BIGINT,
  type VARCHAR(40) NOT NULL,
  severity VARCHAR(10) NOT NULL DEFAULT 'INFO',
  title VARCHAR(200) NOT NULL,
  message TEXT,
  entity_type VARCHAR(40),
  entity_id BIGINT,
  read_at DATETIME(3),
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_notifications_user_id FOREIGN KEY (user_id) REFERENCES users(id),
  CONSTRAINT fk_notifications_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_notifications_company (company_id),
  INDEX ix_notifications_user_id (user_id)
) ENGINE=InnoDB;

CREATE TABLE support_tickets (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  category VARCHAR(20) NOT NULL DEFAULT 'SUPPORT',
  subject VARCHAR(200) NOT NULL,
  description TEXT,
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN',
  priority VARCHAR(10) NOT NULL DEFAULT 'NORMAL',
  created_by_user_id BIGINT,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_support_tickets_created_by_user_id FOREIGN KEY (created_by_user_id) REFERENCES users(id),
  CONSTRAINT fk_support_tickets_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_support_tickets_company (company_id),
  INDEX ix_support_tickets_created_by_user_id (created_by_user_id)
) ENGINE=InnoDB;

CREATE TABLE customer_feedback (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  customer_id BIGINT,
  shipment_id BIGINT,
  kind VARCHAR(20) NOT NULL DEFAULT 'FEEDBACK',
  rating INT,
  comment TEXT,
  status VARCHAR(20) NOT NULL DEFAULT 'OPEN',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT fk_customer_feedback_customer_id FOREIGN KEY (customer_id) REFERENCES customers(id),
  CONSTRAINT fk_customer_feedback_shipment_id FOREIGN KEY (shipment_id) REFERENCES shipments(id),
  CONSTRAINT fk_customer_feedback_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_customer_feedback_company (company_id),
  INDEX ix_customer_feedback_customer_id (customer_id),
  INDEX ix_customer_feedback_shipment_id (shipment_id)
) ENGINE=InnoDB;


-- High-volume GPS positions (written only by authenticated driver apps / registered GPS devices; never simulated)
CREATE TABLE gps_locations (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  vehicle_id BIGINT NULL,
  driver_id BIGINT NULL,
  journey_id BIGINT NULL,
  latitude DECIMAL(10,7) NOT NULL,
  longitude DECIMAL(10,7) NOT NULL,
  speed_kmh DECIMAL(6,2) NULL,
  heading_deg DECIMAL(5,1) NULL,
  accuracy_m DECIMAL(8,2) NULL,
  source VARCHAR(20) NOT NULL,           -- DRIVER_APP or GPS_DEVICE
  recorded_at DATETIME(3) NOT NULL,
  received_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  CONSTRAINT fk_gps_company FOREIGN KEY (company_id) REFERENCES companies(id),
  CONSTRAINT fk_gps_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),
  CONSTRAINT fk_gps_driver FOREIGN KEY (driver_id) REFERENCES drivers(id),
  INDEX ix_gps_vehicle_time (company_id, vehicle_id, recorded_at),
  INDEX ix_gps_journey (journey_id, recorded_at)
) ENGINE=InnoDB;

CREATE TABLE ai_usage (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  company_id BIGINT NOT NULL,
  user_id BIGINT NULL,
  feature VARCHAR(40) NOT NULL,
  model VARCHAR(120) NOT NULL,
  prompt_tokens INT NOT NULL DEFAULT 0,
  completion_tokens INT NOT NULL DEFAULT 0,
  success BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_ai_company FOREIGN KEY (company_id) REFERENCES companies(id),
  INDEX ix_ai_company_time (company_id, created_at)
) ENGINE=InnoDB;
